 "Mais usada": {
  "en": "Most used",
  "es": "Más usada",
  "fr": "La plus utilisée"
 },
 "Com uma estética visual de destaque e uma vitrine inspirada nas plataformas de streaming, a plataforma oferece uma experiência envolvente. Seu painel administrativo intuitivo simplifica a navegação, tornando a utilização desta plataforma sensacional e recompensadora.": {
  "en": "With a standout visual aesthetic and a showcase inspired by streaming platforms, the platform offers an engaging experience. Its intuitive admin panel simplifies navigation, making the platform a great, rewarding experience to use.",
  "es": "Con una estética visual destacada y una vitrina inspirada en las plataformas de streaming, la plataforma ofrece una experiencia envolvente. Su panel administrativo intuitivo simplifica la navegación, haciendo que usar esta plataforma sea sensacional y gratificante.",
  "fr": "Avec une esthétique visuelle remarquable et une vitrine inspirée des plateformes de streaming, la plateforme offre une expérience immersive. Son tableau de bord d'administration intuitif simplifie la navigation et rend l'utilisation de la plateforme formidable et gratifiante."
 },
