 "Fluxo ilustrado: um anúncio genérico leva o cliente direto para dentro da Área de Membros Astron, já engajado desde o primeiro clique.": {
  "en": "Illustrated flow: a generic ad takes the customer straight into the Astron Members Area, already engaged from the first click.",
  "es": "Flujo ilustrado: un anuncio genérico lleva al cliente directo al Área de Miembros Astron, ya comprometido desde el primer clic.",
  "fr": "Parcours illustré : une annonce générique conduit le client directement dans l'espace membres Astron, déjà engagé dès le premier clic."
 },
